// Parse LLM report and combine with metrics
const llmResponse = $json;
const metrics = $('Calculate Daily Metrics').first().json;

let reportText = '';

try {
  reportText = llmResponse.choices[0].message.content;
} catch (e) {
  // Fallback report if LLM fails
  reportText = `📊 *Divine Hindu - Daily Social Media Report*\n` +
    `📅 Date: ${metrics.report_date}\n\n` +
    `*Comment Summary:*\n` +
    `• Total Comments: ${metrics.comments.total}\n` +
    `• Complaints: ${metrics.comments.complaints}\n` +
    `• Escalations: ${metrics.comments.escalations}\n` +
    `• Avg Response: ${metrics.comments.avg_response_time_readable}\n\n` +
    `*DM Summary:*\n` +
    `• Total DMs: ${metrics.dms.total}\n` +
    `• Hot Leads: ${metrics.dms.hot_leads}\n` +
    `• Support Requests: ${metrics.dms.support_requests}\n` +
    `• Avg Response: ${metrics.dms.avg_response_time_readable}\n\n` +
    `*Totals:*\n` +
    `• Total Interactions: ${metrics.summary.total_interactions}\n` +
    `• Total Hot Leads: ${metrics.summary.total_hot_leads}\n` +
    `• Total Complaints: ${metrics.summary.total_complaints}\n\n` +
    `_Auto-generated fallback report (LLM unavailable)_`;
}

// Build structured output
return [{
  json: {
    report_date: metrics.report_date,
    report_text: reportText,
    metrics: metrics,
    // Slack-formatted header
    slack_header: `🕉️ *Divine Hindu - Daily Social Media Report* | 📅 ${metrics.report_date}`,
    // Email subject
    email_subject: `Divine Hindu - Daily Social Media Report - ${metrics.report_date}`,
    // Quick stats for sheets
    total_comments: metrics.comments.total,
    total_dms: metrics.dms.total,
    total_interactions: metrics.summary.total_interactions,
    hot_leads: metrics.summary.total_hot_leads,
    complaints: metrics.summary.total_complaints,
    escalations: metrics.summary.total_escalations,
    comment_avg_response: metrics.comments.avg_response_time_readable,
    dm_avg_response: metrics.dms.avg_response_time_readable,
    requires_attention: metrics.summary.requires_attention
  }
}];

