const item = $input.item.json;
const phoneNumberId = $env.META_WHATSAPP_PHONE_NUMBER_ID || '';
const toNumber = $env.WHATSAPP_ALERT_TO_NUMBER || '';
const token = $env.META_ACCESS_TOKEN;

if (!phoneNumberId || !toNumber) {
  return [{ json: { ...item, whatsapp_result: 'skipped — WHATSAPP env vars not set' } }];
}

const msgText = '🚨 Divine Hindu — Attention Required!\n\n' +
  'Date: ' + item.report_date + '\n' +
  'Complaints: ' + item.complaints + '\n' +
  'Escalations: ' + item.escalations + '\n' +
  'Hot Leads: ' + item.hot_leads + '\n\n' +
  'Please check Slack for full report.';

try {
  const resp = await fetch(`https://graph.facebook.com/v19.0/${phoneNumberId}/messages`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
    body: JSON.stringify({ messaging_product: 'whatsapp', to: toNumber, type: 'text', text: { body: msgText } })
  });
  const result = await resp.json();
  return [{ json: { ...item, whatsapp_result: result } }];
} catch(e) {
  return [{ json: { ...item, whatsapp_result: 'error: ' + e.message } }];
}
